#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
want=$(printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t13:00\t14:00\ty')
[ "$(cat "$t")" = "$want" ] || { echo "header or other booking changed: $(cat "$t")"; fail=1; }
o=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); c=$?
[ "$c" = 1 ] || { echo "not found should exit 1, got $c"; fail=1; }
[ -z "$o" ] || { echo "not found should print nothing on stdout: $o"; fail=1; }
e=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null)
[ "$e" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found message on stderr: $e"; fail=1; }
rm -f "$t"
t2=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\n' > "$t2"
BOOKINGS=$t2 bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null || { echo "cancel failed (other room)"; fail=1; }
want2=$(printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t09:00\t10:00\ty')
[ "$(cat "$t2")" = "$want2" ] || { echo "another room's booking at the same time changed: $(cat "$t2")"; fail=1; }
rm -f "$t2"
o=$(bash src/cancel.sh aoi 2>/dev/null); c=$?
[ "$c" = 2 ] && [ -z "$o" ] || { echo "usage should exit 2 with empty stdout, got $c: $o"; fail=1; }
exit $fail

